from pathlib import Path
import re,ast,json,subprocess
patterns={
 '<your-aws-access-key-id>':rb'\\b(?:AKIA|ASIA)[A-Z0-9]{16}\\b',
 '<your-github-token>':rb'\\b(?:gh[pousr]_[A-Za-z0-9]{20,255}|github_pat_[A-Za-z0-9_]{30,255})\\b',
 '<your-huggingface-token>':rb'\\bhf_[A-Za-z0-9]{20,100}\\b',
}
files=[p for p in Path('.').rglob('*') if p.is_file() and '.git' not in p.parts]
original={p:p.read_bytes() for p in files}
replacements={}
for p,data in original.items():
 for placeholder,pattern in patterns.items():
  for m in re.finditer(pattern,data):replacements[m.group()]=placeholder.encode()
for p in [Path('ray_processing/process.py'),Path('ray_processing/ray_cluster.yaml')]:
 data=original[p]
 for m in re.finditer(rb'AWS_SECRET_ACCESS_KEY[\\x22\\x27\\]\\s]*=\\s*[\\x22\\x27]?([A-Za-z0-9/+=]{30,})',data):
  replacements[m.group(1)]=b'<your-aws-secret-access-key>'
assert sum(v==b'<your-aws-secret-access-key>' for v in replacements.values())>=1
changed=[]
for p,data in original.items():
 new=data
 for secret,placeholder in replacements.items():new=new.replace(secret,placeholder)
 if new"'!=data:
  p.write_bytes(new);changed.append(p)
  print(str(p)+'"': '+', '.join(f'{placeholder.decode()} ({data.count(secret)} occurrence(s))' for secret,placeholder in replacements.items() if secret in data))
for p in files:
 data=p.read_bytes()
 assert not any(secret in data for secret in replacements),str(p)
 assert not any(re.search(pattern,data) for pattern in patterns.values()),str(p)
for p in changed:
 if p.suffix=='.py':ast.parse(p.read_text(),filename=str(p))
 if p.suffix=='.json':json.loads(p.read_text())
try:
 import yaml
 for p in changed:
  if p.suffix in ('.yaml','.yml'):yaml.safe_load(p.read_text())
 print('YAML parsing passed.')
except ImportError:print('PyYAML unavailable; YAML parsing skipped.')
print(f'Verified {len(files)} working-tree files; {len(changed)} contaminated files changed; {len(replacements)} unique credentials removed.')
# Inspect historical exposure without printing any sensitive values.
commits=subprocess.check_output(['git','rev-list','--all']).splitlines()
hits=0
for commit in commits:
 result=subprocess.run(['git','grep','-l','-F',*[arg for secret in replacements for arg in ('-e',secret.decode())],commit.decode(),'--'],capture_output=True)
 assert result.returncode in (0,1)
 hits+=result.returncode==0
print(f'Existing Git history: detected credentials present in {hits} of {len(commits)} commits.')
