from pathlib import Path
import re,json
credential=re.compile(r'(?i)(?:\\b(?:api[_-]?key|[\\w]*secret[\\w]*|[\\w]*password[\\w]*|[\\w]*access_key[\\w]*|[\\w]*token[\\w]*)[\\x22\\x27\\]\\s]*[:=]\\s*[\\x22\\x27](["'^'"\\x22\\x27\\r\\n]{8,})|--(?:token|api-key|password)\\s+(\\S+)|https?://(["'^'"\\s/@]+:["'^'"\\s/@]+)@|-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----)')
for p in Path('.').rglob('*'):
 if not p.is_file() or '.git' in p.parts:continue
 try:s=p.read_text()
 except (UnicodeError,OSError):continue
 if p.suffix=='.json':
  try:
   obj=json.loads(s)
   def values(x):
    if isinstance(x,str):yield x
    elif isinstance(x,dict):
     for v in x.values():yield from values(v)
    elif isinstance(x,list):
     for v in x:yield from values(v)
   s+='\\n'+'\\n'.join(values(obj))
  except ValueError:pass
 for m in credential.finditer(s):
  v=next((v for v in m.groups() if v is not None),'PRIVATE KEY')
  if '<your-' in v or '[REDACTED' in v:continue
  print(f'{p}: possible credential literal; length={len(v)}; context='+re.sub(r'[A-Za-z0-9/+_-]{8,}','[MASKED]',s[max(0,m.start()-30):m.start()])[:80])
print('Additional credential-literal scan complete.')
